function shallowEqual(a, b) {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  return ka.every((k) => Object.is(a[k], b[k]));
}

function memoize(fn) {
  let lastArgs = null;
  let lastResult;
  let hasCache = false;
  return function (...args) {
    if (
      hasCache &&
      lastArgs.length === args.length &&
      lastArgs.every((v, i) => shallowEqual(v, args[i]))
    ) {
      console.log("  cache HIT — returning cached result");
      return lastResult;
    }
    console.log("  cache MISS — recomputing");
    lastArgs = args;
    lastResult = fn(...args);
    hasCache = true;
    return lastResult;
  };
}

let computeCalls = 0;
function expensiveTotal(items) {
  computeCalls++;
  return items.reduce((s, it) => s + it.price, 0);
}

const memoTotal = memoize(expensiveTotal);
const cart1 = [{ price: 10 }, { price: 20 }];
console.log("call 1 (fresh cart):", memoTotal(cart1));
console.log("call 2 (same ref):", memoTotal(cart1));
console.log("call 3 (equal copy):", memoTotal([{ price: 10 }, { price: 20 }]));
console.log("call 4 (changed):", memoTotal([{ price: 10 }, { price: 99 }]));
console.log("real computations performed:", computeCalls);

