const tree = {
  name: "App",
  state: ["query"],
  memoized: false,
  children: [
    { name: "SearchBox", propsFrom: ["query"], memoized: true, children: [] },
    {
      name: "ResultList",
      consumes: ["ResultsContext"],
      memoized: false,
      children: [{ name: "Row", propsFrom: ["item"], memoized: true, children: [] }],
    },
    { name: "ThemeBadge", consumes: ["ThemeContext"], memoized: false, children: [] },
  ],
};

function analyze(node, parentRendered, changed, out) {
  let reason = null;
  if (node.name === changed.state) {
    reason = `state change (${changed.stateVar})`;
  } else if (node.consumes && node.consumes.some((c) => changed.contexts.includes(c))) {
    reason = `consumes ${node.consumes.find((c) => changed.contexts.includes(c))} (changed)`;
  } else if (parentRendered) {
    const propsChanged = (node.propsFrom || []).some((p) => changed.props.includes(p));
    if (node.memoized && !propsChanged) {
      out.push(`${node.name}: SKIPS render (memoized, props unchanged)`);
      return;
    }
    reason = node.memoized ? "parent rendered, props changed" : "parent rendered (not memoized)";
  }
  if (reason) {
    out.push(`${node.name}: RE-RENDERS — ${reason}`);
    for (const child of node.children || []) analyze(child, true, changed, out);
  } else {
    for (const child of node.children || []) analyze(child, false, changed, out);
  }
}

let out = [];
console.log('=== Event A: App.setQuery("react") ===');
analyze(tree, false, { state: "App", stateVar: "query", contexts: [], props: ["query"] }, out);
console.log(out.join("\n"));

out = [];
console.log("=== Event B: ThemeContext value changes ===");
analyze(tree, false, { state: null, stateVar: null, contexts: ["ThemeContext"], props: [] }, out);
console.log(out.join("\n"));

