function windowFor(scrollTop, itemCount, rowHeight, viewportHeight, overscan) {
  const totalHeight = itemCount * rowHeight;
  const firstVisible = Math.floor(scrollTop / rowHeight);
  const start = Math.max(0, firstVisible - overscan);
  const lastVisible = Math.ceil((scrollTop + viewportHeight) / rowHeight) - 1;
  const end = Math.min(itemCount - 1, lastVisible + overscan);
  return { start, end, count: end - start + 1, offsetY: start * rowHeight, totalHeight };
}

const ITEMS = 10000;
const ROW_H = 48;
const VIEW_H = 600;
const OVERSCAN = 5;

console.log(`list: ${ITEMS} rows x ${ROW_H}px, viewport ${VIEW_H}px, overscan ${OVERSCAN}`);
const w0 = windowFor(0, ITEMS, ROW_H, VIEW_H, OVERSCAN);
console.log(`total scroll height: ${w0.totalHeight}px`);
console.log(`scrollTop=0     -> rows ${w0.start}..${w0.end} (${w0.count} rows), offsetY=${w0.offsetY}px`);
const w1 = windowFor(12000, ITEMS, ROW_H, VIEW_H, OVERSCAN);
console.log(`scrollTop=12000 -> rows ${w1.start}..${w1.end} (${w1.count} rows), offsetY=${w1.offsetY}px`);
console.log(`without virtualization: ${ITEMS} DOM rows; with: ~${w0.count}-${w1.count} — a 99.8% reduction`);

