const candidates = [
  { name: "LandingPage", sizeKB: 180, neededFor: "initial paint" },
  { name: "AdminDashboard", sizeKB: 420, neededFor: "admin click" },
  { name: "ChartWidget", sizeKB: 260, neededFor: "dashboard tab" },
  { name: "SettingsModal", sizeKB: 40, neededFor: "settings click" },
  { name: "CheckoutFlow", sizeKB: 310, neededFor: "buy click", prefetch: true },
];

function decide(c) {
  if (c.neededFor === "initial paint") return ["KEEP", "needed for first paint"];
  if (c.sizeKB >= 100) {
    const reason = "big and not needed upfront" + (c.prefetch ? "; prefetch on hover/intent" : "");
    return ["LAZY-LOAD", reason];
  }
  return ["KEEP", "small enough that a split is not worth the waterfall"];
}

for (const c of candidates) {
  const [decision, reason] = decide(c);
  console.log(`${c.name} (${c.sizeKB}KB, ${c.neededFor}): ${decision} — ${reason}`);
}

